              >
                {changingRoomId !== null
                  ? "กำลังบันทึก..."
                  : confirmRoom.nextStatus
                    ? "ยืนยันเปิดใช้งาน"
                    : "ยืนยันปิดใช้งาน"}
              </button>
            </div>
          </section>
        </div>
      )}
    </div>
  );
}

export default AdminRooms;
